import contextlib
import io
import subprocess
import sys
import unittest

import numpy as np

from main import VoltageSource, RCCircuit, RLCircuit, SeriesRLC


def equation_for(circuit):
    with contextlib.redirect_stdout(io.StringIO()):
        return circuit.calculate_response()


def evaluate(equation, t):
    # Only evaluate equations generated by our calculator, with no builtins.
    return eval(equation, {'__builtins__': {}, 'exp': np.exp,
                           'sin': np.sin, 'cos': np.cos, 't': t})


def source_value(source, t):
    if source.source_type == 'DC':
        return source.amplitude
    if source.source_type == 'Sinusoidal':
        return source.amplitude * np.sin(2 * np.pi * source.frequency * t
                                         + np.deg2rad(source.phase))
    return source.amplitude * np.exp(source.rate * t)


class ResponseTests(unittest.TestCase):
    def test_equations_and_initial_conditions(self):
        sources = [VoltageSource('DC', 10), VoltageSource('Sinusoidal', 4, 0.7, 35),
                   VoltageSource('Sinusoidal', 4, 0, 90),
                   VoltageSource('Exponential', 3, rate=-0.8),
                   VoltageSource('Exponential', 2, rate=0.4)]
        for source in sources:
            circuits = [RCCircuit(3, 0.4, source, 2), RLCircuit(3, 0.4, source, 2)]
            circuits += [SeriesRLC(r, 1, 1, source, 2, 0.3) for r in (1, 2, 3)]
            for circuit in circuits:
                with self.subTest(source=source.source_type, circuit=type(circuit), R=circuit.R):
                    equation = equation_for(circuit)
                    self.assertAlmostEqual(evaluate(equation, 0), 2)
                    # Complex step computes the first derivative without subtractive cancellation.
                    initial_slope = evaluate(equation, 1e-20j).imag / 1e-20
                    if isinstance(circuit, SeriesRLC):
                        self.assertAlmostEqual(initial_slope, 0.3)
                    for t in (0.1, 0.8, 2):
                        y = evaluate(equation, t)
                        dy = evaluate(equation, t + 1e-20j).imag / 1e-20
                        h = 0.001
                        ddy = (-evaluate(equation, t + 2*h) + 16*evaluate(equation, t + h)
                               - 30*y + 16*evaluate(equation, t - h)
                               - evaluate(equation, t - 2*h)) / (12 * h ** 2)
                        if isinstance(circuit, RCCircuit):
                            lhs = circuit.R * circuit.C * dy + y
                        elif isinstance(circuit, RLCircuit):
                            lhs = circuit.L * dy + circuit.R * y
                        else:
                            lhs = circuit.L * circuit.C * ddy + circuit.R * circuit.C * dy + y
                        self.assertAlmostEqual(lhs, source_value(source, t), delta=2e-6)

    def test_matching_exponential_rates(self):
        source = VoltageSource('Exponential', 2, rate=-1)
        for circuit in (RCCircuit(1, 1, source, 0), RLCircuit(1, 1, source, 0)):
            equation = equation_for(circuit)
            for t in (0, 0.5, 1):
                self.assertAlmostEqual(evaluate(equation, t), 2 * t * np.exp(-t))
        equation = equation_for(SeriesRLC(3, 1, 0.5, source, 0, 0))
        for t in (0, 0.5, 1):
            self.assertAlmostEqual(evaluate(equation, t),
                                   4 * t * np.exp(-t) - 4 * np.exp(-t) + 4 * np.exp(-2 * t))
        equation = equation_for(SeriesRLC(2, 1, 1, source, 0, 0))
        for t in (0, 0.5, 1):
            self.assertAlmostEqual(evaluate(equation, t), t ** 2 * np.exp(-t))

    def test_dc_regression(self):
        source = VoltageSource('DC', 10)
        equation = equation_for(RCCircuit(1000, 0.0001, source, 0))
        self.assertAlmostEqual(evaluate(equation, 0.1), 10 * (1 - np.exp(-1)))
        source = VoltageSource('DC', 20)
        equation = equation_for(RLCircuit(10, 2, source, 0))
        self.assertAlmostEqual(evaluate(equation, 0.2), 2 * (1 - np.exp(-1)))

    def test_cli_all_sources_and_circuits(self):
        for circuit, components, initial in [('1', ['1', '1'], ['0']),
                                              ('2', ['1', '1'], ['0']),
                                              ('3', ['2', '1', '1'], ['0', '0'])]:
            for source in (['1', '10'], ['2', '10', '1', '30'], ['3', '10', '-1']):
                data = '\n'.join([circuit] + components + source + initial + ['4', ''])
                result = subprocess.run([sys.executable, 'main.py'], input=data, text=True,
                                        capture_output=True, timeout=10, check=True)
                self.assertIn('(t) = ', result.stdout)
                self.assertIn('Exiting program.', result.stdout)
                self.assertNotIn('nan', result.stdout)
                self.assertNotIn('Re[', result.stdout)

    def test_menu_conditions(self):
        for data, message in [('9\n4\n', 'Invalid choice.'),
                              ('1\n0\n4\n', 'R must be positive.'),
                              ('1\n1\n1\n9\n4\n', 'Invalid source choice.')]:
            result = subprocess.run([sys.executable, 'main.py'], input=data,
                                    text=True, capture_output=True, timeout=10, check=True)
            self.assertIn(message, result.stdout)
            self.assertIn('Exiting program.', result.stdout)


if __name__ == '__main__':
    unittest.main()
